export function PersonasPanel() {
  const personas = useAppStore((s) => s.personas);
  const [id, setId] = useState(personas[0]?.id);
  // list rail + editor — reads/writes the GLOBAL store via the bsc bridge
  return <Row><List .../><Editor .../></Row>;
}

@Service
class PersonaService(private val store: JsonStore) {
  fun list(): List<Persona> = store.readAll("personas")
  fun set(p: Persona) = store.write("personas/${p.id}", p)
  fun remove(id: String) = store.delete("personas/$id")
}

@Service
class BscBridge {
  fun run(argv: List<String>, projectKey: String? = null): String =
    exec(listOf("bsc") + keyArgs(projectKey) + argv).stdout
  fun write(argv: List<String>, body: Any) =
    exec(listOf("bsc") + argv, stdin = json(body))
}

pub struct CommandRouter { handlers: HashMap<String, Handler> }
impl CommandRouter {
  pub fn register(&mut self, name: &str, h: Handler) {
    self.handlers.insert(name.into(), h);
  }
}

pub fn watch(path: &Path, on_change: impl Fn(Event)) -> Result<()> {
  let mut w = notify::recommended_watcher(move |ev| on_change(ev))?;
  w.watch(path, RecursiveMode::Recursive)?;
  Ok(())
}
